export class UploadManagerError extends Error {
    code;
    context;
    constructor(code, message, context, options){
        super(message, options), this.code = code, this.context = context;
        this.name = "UploadManagerError";
    }
}
export const SYSTEM_UPLOAD_MANAGER_CLOCK = {
    now: Date.now,
    setTimeout: (callback, delayMs)=>setTimeout(callback, delayMs),
    clearTimeout: (timer)=>clearTimeout(timer)
};
const DEFAULT_MAX_ACTIVE = 2;
const DEFAULT_MAX_QUEUED = 4;
const DEFAULT_QUEUE_TIMEOUT_MS = 5_000;
export const MAX_UPLOAD_QUEUE_TIMEOUT_MS = 2_147_483_647;
function createDeferred() {
    let resolve;
    let reject;
    const promise = new Promise((res, rej)=>{
        resolve = res;
        reject = rej;
    });
    return {
        promise,
        resolve,
        reject
    };
}
function nonNegativeInteger(value, name) {
    if (!Number.isSafeInteger(value) || value < 0) {
        throw new TypeError(`${name} must be a non-negative safe integer`);
    }
    return value;
}
function positiveInteger(value, name) {
    if (!Number.isSafeInteger(value) || value < 1) {
        throw new TypeError(`${name} must be a positive safe integer`);
    }
    return value;
}
function contextError(code, context, cause) {
    const message = code === "queue-full" ? "upload queue is full" : code === "queue-timeout" ? "upload queue deadline exceeded" : code === "upload-cancelled" ? "upload request was cancelled" : code === "device-session-changed" ? `device session ${context.generation} is no longer active` : "upload manager is closed";
    return new UploadManagerError(code, message, context, {
        cause
    });
}
function isUploadCleanupFailure(error) {
    if (typeof error !== "object" || error === null || !("code" in error)) {
        return false;
    }
    return error.code === "upload-cleanup-failed" || error.code === "adb-cleanup-failed";
}
/**
 * Bounds upload work and owns its cancellation/cleanup lifecycle.
 *
 * A slot is not released until the operation promise settles after an abort.
 * Callers should stop their I/O when `signal` aborts and resolve/reject only
 * after their temporary-file and subprocess cleanup has finished.
 */ export class UploadManager {
    #maxActive;
    #maxQueued;
    #queueTimeoutMs;
    #clock;
    #queue = [];
    #active = new Map();
    #cancelledGenerations = new Set();
    #totals = {
        accepted: 0,
        started: 0,
        completed: 0,
        failed: 0,
        cancelled: 0,
        rejected: 0,
        timedOut: 0
    };
    #nextId = 1;
    #closed = false;
    #closePromise = null;
    constructor(options = {}){
        this.#maxActive = positiveInteger(options.maxActive ?? DEFAULT_MAX_ACTIVE, "maxActive");
        this.#maxQueued = nonNegativeInteger(options.maxQueued ?? DEFAULT_MAX_QUEUED, "maxQueued");
        this.#queueTimeoutMs = nonNegativeInteger(options.queueTimeoutMs ?? DEFAULT_QUEUE_TIMEOUT_MS, "queueTimeoutMs");
        if (this.#queueTimeoutMs > MAX_UPLOAD_QUEUE_TIMEOUT_MS) {
            throw new TypeError(`queueTimeoutMs must be at most ${MAX_UPLOAD_QUEUE_TIMEOUT_MS}`);
        }
        this.#clock = options.clock ?? SYSTEM_UPLOAD_MANAGER_CLOCK;
    }
    run(options, operation) {
        const context = this.#copyContext(options.context);
        if (this.#closed) {
            return this.#rejectImmediately(contextError("closed", context));
        }
        if (this.#cancelledGenerations.has(context.generation)) {
            return this.#rejectImmediately(contextError("device-session-changed", context));
        }
        if (options.sessionSignal?.aborted) {
            return this.#rejectImmediately(contextError("device-session-changed", context, options.sessionSignal.reason));
        }
        if (options.requestSignal?.aborted) {
            return this.#rejectImmediately(contextError("upload-cancelled", context, options.requestSignal.reason));
        }
        if (this.#active.size >= this.#maxActive && this.#queue.length >= this.#maxQueued) {
            return this.#rejectImmediately(contextError("queue-full", context));
        }
        const job = {
            id: this.#nextId++,
            context,
            operation,
            controller: new AbortController(),
            deferred: createDeferred(),
            enqueuedMs: this.#clock.now(),
            state: "queued",
            queueTimer: null,
            cancellation: null,
            listenerCleanup: [],
            cleanup: null
        };
        this.#totals.accepted++;
        this.#listenForAbort(job, options.requestSignal, "upload-cancelled");
        this.#listenForAbort(job, options.sessionSignal, "device-session-changed");
        if (job.cancellation) {
            this.#finishQueuedCancellation(job);
            return job.deferred.promise;
        }
        if (this.#active.size < this.#maxActive) {
            this.#start(job);
        } else {
            this.#queue.push(job);
            const timer = this.#clock.setTimeout(()=>{
                if (job.state !== "queued") return;
                this.#cancel(job, contextError("queue-timeout", job.context));
            }, this.#queueTimeoutMs);
            if (job.state === "queued") job.queueTimer = timer;
            else this.#clock.clearTimeout(timer);
        }
        return job.deferred.promise;
    }
    async cancelGeneration(generation, cause) {
        nonNegativeInteger(generation, "generation");
        this.#cancelledGenerations.add(generation);
        const cleanups = [];
        for (const job of [
            ...this.#queue
        ]){
            if (job.context.generation !== generation) continue;
            this.#cancel(job, contextError("device-session-changed", job.context, cause));
        }
        for (const job of this.#active.values()){
            if (job.context.generation !== generation) continue;
            this.#cancel(job, contextError("device-session-changed", job.context, cause));
            if (job.cleanup) cleanups.push(job.cleanup);
        }
        await Promise.allSettled(cleanups);
    }
    close(cause) {
        if (this.#closePromise) return this.#closePromise;
        let finish;
        this.#closePromise = new Promise((resolve)=>{
            finish = resolve;
        });
        this.#closed = true;
        const cleanups = [];
        for (const job of [
            ...this.#queue
        ]){
            this.#cancel(job, contextError("closed", job.context, cause));
        }
        for (const job of this.#active.values()){
            this.#cancel(job, contextError("closed", job.context, cause));
            if (job.cleanup) cleanups.push(job.cleanup);
        }
        void Promise.allSettled(cleanups).then(()=>finish());
        return this.#closePromise;
    }
    snapshot() {
        const now = this.#clock.now();
        return {
            closed: this.#closed,
            active: this.#active.size,
            queued: this.#queue.length,
            oldestQueuedAgeMs: this.#queue.length === 0 ? null : Math.max(0, now - this.#queue[0].enqueuedMs),
            limits: {
                active: this.#maxActive,
                queued: this.#maxQueued,
                queueTimeoutMs: this.#queueTimeoutMs
            },
            totals: {
                ...this.#totals
            }
        };
    }
    #copyContext(context) {
        if (typeof context.serial !== "string" || context.serial.length === 0) {
            throw new TypeError("context.serial must be a non-empty string");
        }
        nonNegativeInteger(context.generation, "context.generation");
        return {
            serial: context.serial,
            generation: context.generation
        };
    }
    #rejectImmediately(error) {
        this.#totals.rejected++;
        return Promise.reject(error);
    }
    #listenForAbort(job, signal, code) {
        if (!signal) return;
        const onAbort = ()=>{
            this.#cancel(job, contextError(code, job.context, signal.reason));
        };
        signal.addEventListener("abort", onAbort, {
            once: true
        });
        job.listenerCleanup.push(()=>signal.removeEventListener("abort", onAbort));
        if (signal.aborted) onAbort();
    }
    #start(job) {
        if (job.state !== "queued") return;
        job.state = "active";
        this.#active.set(job.id, job);
        this.#totals.started++;
        let value;
        let operationError;
        let operationFailed = false;
        const cleanup = Promise.resolve().then(()=>{
            if (job.cancellation) throw job.cancellation;
            return job.operation({
                context: job.context,
                signal: job.controller.signal
            });
        }).then((result)=>{
            value = result;
        }, (error)=>{
            operationFailed = true;
            operationError = error;
        }).then(()=>{
            this.#finishActive(job, value, operationFailed, operationError);
        });
        job.cleanup = cleanup;
        this.#clearQueueTimer(job);
    }
    #finishActive(job, value, operationFailed, operationError) {
        if (job.state !== "active") return;
        job.state = "finished";
        this.#active.delete(job.id);
        this.#disposeJob(job);
        if (operationFailed && isUploadCleanupFailure(operationError)) {
            // Cancellation normally wins races, but hiding a cleanup failure would
            // make a leaked staging directory invisible to the caller.
            this.#totals.failed++;
            job.deferred.reject(operationError);
        } else if (job.cancellation) {
            this.#recordCancellation(job.cancellation);
            job.deferred.reject(job.cancellation);
        } else if (operationFailed) {
            this.#totals.failed++;
            job.deferred.reject(operationError);
        } else {
            this.#totals.completed++;
            job.deferred.resolve(value);
        }
        this.#drain();
    }
    #cancel(job, error) {
        if (job.state === "finished" || job.cancellation) return;
        job.cancellation = error;
        job.controller.abort(error);
        if (job.state === "queued") this.#finishQueuedCancellation(job);
    }
    #finishQueuedCancellation(job) {
        if (job.state !== "queued" || !job.cancellation) return;
        job.state = "finished";
        const index = this.#queue.indexOf(job);
        if (index >= 0) this.#queue.splice(index, 1);
        this.#disposeJob(job);
        this.#recordCancellation(job.cancellation);
        job.deferred.reject(job.cancellation);
        this.#drain();
    }
    #recordCancellation(error) {
        if (error.code === "queue-timeout") this.#totals.timedOut++;
        else this.#totals.cancelled++;
    }
    #disposeJob(job) {
        this.#clearQueueTimer(job);
        for (const cleanup of job.listenerCleanup.splice(0))cleanup();
    }
    #clearQueueTimer(job) {
        if (job.queueTimer === null) return;
        this.#clock.clearTimeout(job.queueTimer);
        job.queueTimer = null;
    }
    #drain() {
        if (this.#closed) return;
        while(this.#active.size < this.#maxActive){
            const job = this.#queue.shift();
            if (!job) return;
            if (job.state !== "queued") continue;
            this.#start(job);
        }
    }
}
